mapper.select:
select L1.user_id as resource_id, count(L1.lesson_id) as lesson_record_count, count(L2.id) as finish_report_count, avg(L3.score) as report_average, count(L4.id) as finish_practice_count from oj_lesson_record L1 left join oj_note L2 on L2.note_type = #{report_code} and L1.user_id = L2.user_id and L1.lesson_id = L2.business_id left join oj_note_evaluate L3 on L2.resource_id = L3.note_id left join oj_lesson_paper_evaluate L4 on L1.lesson_id = L4.lesson_id and L1.user_id = L4.submit_user_id
L1.user_id in #{user_id}
group by L1.user_id;

select user_id, count(*) as `count` from oj_lesson_record
where user_id in #{user_id}
group by user_id order by `count` desc limit 5;

select T1.user_id, count(T2.resource_id) as `count`
from oj_note T1 left join oj_note_evaluate T2 on T1.resource_id = T2.note_id
where T1.note_type = #{report_code} and T2.passed = 1 and T1.user_id in #{user_id}
group by T1.user_id order by `count` desc;

select submit_user_id as user_id, count(*) as `count`
from oj_lesson_paper_evaluate
where submit_user_id in #{user_id}
group by user_id order by count desc;
